xpath.script:
function switchNestedPane(element, paneId) {
var items = element.parentNode.getElementsByClassName('vertical_menu_item');
for (var i = 0; i < items.length; i++) {
items[i].classList.remove('active');
}
element.classList.add('active');

var panes = element.parentNode.parentNode.getElementsByClassName('custom_nested_pane');
for (var j = 0; j < panes.length; j++) {
panes[j].classList.add('d-none');
}
document.getElementById(paneId).classList.remove('d-none');
}

function switchHistoryPane(element, paneId) {
var items = element.parentNode.getElementsByClassName('history_menu_item');
for (var i = 0; i < items.length; i++) {
items[i].classList.remove('active');
}
element.classList.add('active');

var panes = element.parentNode.parentNode.getElementsByClassName('history_pane');
for (var j = 0; j < panes.length; j++) {
panes[j].classList.add('d-none');
}
document.getElementById(paneId).classList.remove('d-none');
}
